import json
import os
import re
import shutil
from pathlib import Path

SCRIPT_DIR = Path(__file__).parent.resolve()
OPENCODE_JSON = SCRIPT_DIR / "opencode.json"
ENV_FILE = SCRIPT_DIR / ".env"
API_KEYS_DIR = SCRIPT_DIR / "api_keys"

ENV_PATTERN = re.compile(r'\{env:([A-Z_][A-Z0-9_]*)\}', re.IGNORECASE)


def discover_env_vars(config: dict, parent_path: str = "") -> list[str]:
    vars_found = []
    for key, value in config.items():
        path = f"{parent_path}.{key}" if parent_path else key
        if isinstance(value, str):
            for match in ENV_PATTERN.finditer(value):
                vars_found.append(match.group(1))
        elif isinstance(value, dict):
            vars_found.extend(discover_env_vars(value, path))
    return vars_found


def load_env_file(env_path: Path) -> dict[str, str]:
    env_vars = {}
    if not env_path.exists():
        print(f"[WARN] .env not found at {env_path}")
        return env_vars
    for line in env_path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" in line:
            k, v = line.split("=", 1)
            k = k.strip()
            v = v.strip().strip('"').strip("'")
            env_vars[k] = v
    return env_vars


KEY_NAME_PATTERNS = ["API_KEY", "SECRET", "TOKEN", "PASSWORD", "_KEY", "PERSONAL_ACCESS_TOKEN"]

def looks_like_api_key(name: str) -> bool:
    name = name.upper()
    return any(p.upper() in name for p in KEY_NAME_PATTERNS)


def patch_config(config: dict, updated_vars: list[str]):
    count = 0
    for key, value in config.items():
        if isinstance(value, str):
            for var in updated_vars:
                if f"{{env:{var}}}" in value:
                    config[key] = value.replace(f"{{env:{var}}}", f"{{file:api_keys/{var}}}")
                    count += 1
                    break
        elif isinstance(value, dict):
            count += patch_config(value, updated_vars)
    return count


def main():
    print(f"[sync-env-keys] Folder: {SCRIPT_DIR}")
    print()

    if not ENV_FILE.exists():
        print(f"[ERROR] .env not found at {ENV_FILE}")
        input("(Press Enter to exit)")
        return

    all_env = load_env_file(ENV_FILE)
    print(f"[ENV] Loaded {len(all_env)} key(s) from .env")

    if OPENCODE_JSON.exists():
        try:
            config = json.loads(OPENCODE_JSON.read_text(encoding="utf-8"))
            env_vars = discover_env_vars(config)
        except Exception as e:
            print(f"[WARN] Could not parse opencode.json: {e}")
            env_vars = []
    else:
        env_vars = []
        config = None

    if not env_vars:
        env_vars = [k for k in all_env.keys() if looks_like_api_key(k)]
        print(f"[ENV] No {{env:}} refs in config — using {len(env_vars)} API-key-like key(s) from .env")
    else:
        print(f"[CONFIG] Found {len(env_vars)} {{env:...}} reference(s) in opencode.json")

    env_vars = sorted(set(env_vars))
    print()

    API_KEYS_DIR.mkdir(exist_ok=True)
    written = []
    skipped_existing = []

    for var in env_vars:
        key_file = API_KEYS_DIR / var
        if key_file.exists():
            skipped_existing.append(var)
            continue
        if var in all_env:
            key_file.write
